import re

def parse_color(text):
    if not isinstance(text, str):
        raise ValueError("Input must be a string")
    if not re.fullmatch(r'#[a-fA-F0-9]{3}$|#[a-fA-F0-9]{6}$', text):
        raise ValueError("Invalid color format")
    hex_part = text[1:]
    if len(hex_part) == 3:
        hex_str = ''.join(c * 2 for c in hex_part)
    else:
        hex_str = hex_part
    try:
        r = int(hex_str[0:2], 16)
        g = int(hex_str[2:4], 16)
        b = int(hex_str[4:6], 16)
    except ValueError:
        raise ValueError("Invalid hex value")
    return (r, g, b)

def format_color(rgb):
    if not isinstance(rgb, (tuple, list)) or len(rgb) != 3:
        raise ValueError("Input must be a 3-element sequence")
    try:
        for val in rgb:
            if not isinstance(val, int) or isinstance(val, bool) or not (0 <= val <= 255):
                raise ValueError("Component must be integer in 0-255")
    except TypeError:
        raise ValueError("Component must be integer in 0-255")
    r, g, b = rgb
    def to_hex(val):
        return f"{val:02x}"
    full = [to_hex(c) for c in (r, g, b)]
    short = all(h[0] == h[1] for h in full)
    if short:
        return '#' + ''.join(h[0] for h in full)
    else:
        return '#' + ''.join(full)
