To implement the `cidr_range` function, the approach involves validating the input format, parsing the IP address and prefix length, converting the IP to a 32-bit integer, computing the network range, and converting the results back to dotted decimal notation.

The input string is validated to ensure it follows the correct CIDR notation. Each octet and the prefix length are checked for valid ranges and no leading zeros. The IP is converted to a 32-bit integer, and the network address is derived by masking out the host bits. The first and last addresses are computed using bitwise operations, and the size is calculated as $2^{(32 - n)}$.

```python
def cidr_range(text):
    if not isinstance(text, str):
        raise ValueError
    parts = text.split('/')
    if len(parts) != 2:
        raise ValueError
    ip_str, prefix_str = parts
    if ip_str.count('.') != 3:
        raise ValueError

    def is_valid_part(s, max_val):
        if not s.isdigit():
            return False
        num = int(s)
        if num < 0 or num > max_val:
            return False
        if len(s) > 1 and s[0] == '0':
            return False
        return True

    ip_parts = ip_str.split('.')
    if len(ip_parts) != 4:
        raise ValueError
    for p in ip_parts:
        if not is_valid_part(p, 255):
            raise ValueError

    if not is_valid_part(prefix_str, 32):
        raise ValueError
    n = int(prefix_str)

    def to_int(ip_parts):
        a, b, c, d = map(int, ip_parts)
        return (a << 24) | (b << 16) | (c << 8) | d

    ip_int = to_int(ip_parts)
    host_bits = 32 - n
    network_int = (ip_int >> host_bits) << host_bits
    first_int = network_int
    last_int = network_int | ((1 << host_bits) - 1)
    size = 1 << host_bits

    def to_dotted(x):
        octets = [
            str((x >> 24) & 0xFF),
            str((x >> 16) & 0xFF),
            str((x >> 8) & 0xFF),
            str(x & 0xFF)
        ]
        return '.'.join(octets)

    first = to_dotted(first_int)
    last = to_dotted(last_int)
    return (first, last, size)
