def luhn_valid(number):
    if not isinstance(number, str) or len(number) < 2:
        raise ValueError
    if not number.isdigit():
        raise ValueError
    total = 0
    reversed_digits = list(map(int, reversed(number)))
    for i, digit in enumerate(reversed_digits):
        if i % 2 == 1:
            doubled = digit * 2
            digit = doubled - 9 if doubled > 9 else doubled
        total += digit
    return total % 10 == 0

def luhn_append(partial):
    if not isinstance(partial, str) or len(partial) < 1:
        raise ValueError
    if not partial.isdigit():
        raise ValueError
    # Calculate what the check digit should be
    reversed_partial = list(map(int, reversed(partial)))
    sum_without_check = 0
    for i, digit in enumerate(reversed_partial):
        if i % 2 == 1:
            doubled = digit * 2
            digit = doubled - 9 if doubled > 9 else doubled
        sum_without_check += digit
    # The check digit is what makes (sum_without_check + check_digit) divisible by 10
    check_digit = (10 - (sum_without_check % 10)) % 10
    return partial + str(check_digit)
