        key = _decode(key_encoded)
        value = _decode(value_encoded)
        result.append((key, value))
    return result

def _decode(s):
    i = 0
    result = []
    while i < len(s):
        c = s[i]
        if c == "+":
            result.append(" ")
            i += 1
        elif c == "%":
            if i + 2 >= len(s):
                raise ValueError("incomplete percent escape")
            try:
                code = int(s[i + 1:i + 3], 16)
            except ValueError:
                raise ValueError("invalid hex in percent escape")
            if code > 0x7F:
                raise ValueError("percent escape code exceeds 0x7F")
            result.append(chr(code))
            i += 3
        else:
            if not (c.isalnum() or c in "-._~"):
                raise ValueError(f"invalid character {c!r}")
            result.append(c)
            i += 1
    return "".join(result)

def build_query(pairs):
    if not isinstance(pairs, (list, tuple)):
        raise ValueError("pairs must be list or tuple")
    for key, value in pairs:
        if not isinstance(key, str) or not isinstance(value, str):
            raise ValueError("key and value must be strings")
        if not key:
            raise ValueError("empty key")
        for s in (key, value):
            if any(ord(c) > 127 for c in s):
                raise ValueError("non-ASCII character in key or value")
    return "&".join(_encode(key) + "=" + _encode(value) for key, value in pairs)

def _encode(s):
    result = []
    for c in s:
        if c in "-._~" or c.isalnum():
            result.append(c)
        elif c == " ":
            result.append("+")
        else:
            result.append(f"%{ord(c):02X}")
    return "".join(result)

