To solve the problem, we need to compute the number of integer lattice points on a line segment and generate those points in order. The key insight is that the number of such points is determined by the greatest common divisor (GCD) of the absolute differences of the segment's coordinates. The step between consecutive points is derived from these differences divided by the GCD.

---

```python
import math
from math import gcd

def segment_lattice_count(p, q):
    if not (isinstance(p, (list, tuple)) and isinstance(q, (list, tuple))):
        raise ValueError
    if len(p) != 2 or len(q) != 2:
        raise ValueError
    for x, y in [p, q]:
        if not isinstance(x, int) or not isinstance(y, int):
            if isinstance(x, bool) or isinstance(y, bool):
                raise ValueError
            raise ValueError
    if p == q:
        return 1
    dx = abs(q[0] - p[0])
    dy = abs(q[1] - p[1])
    return gcd(dx, dy) + 1

def segment_lattice_points(p, q):
    if not (isinstance(p, (list, tuple)) and isinstance(q, (list, tuple))):
        raise ValueError
    if len(p) != 2 or len(q) != 2:
        raise ValueError
    for x, y in [p, q]:
        if not isinstance(x, int) or not isinstance(y, int):
            if isinstance(x, bool) or isinstance(y, bool):
                raise ValueError
            raise ValueError
    if p == q:
        return [tuple(p)]
    dx = q[0] - p[0]
    dy = q[1] - p[1]
    dx_abs = abs(dx)
    dy_abs = abs(dy)
    g = gcd(dx_abs, dy_abs)
    step_x = dx // g
    step_y = dy // g
    points = []
    x, y = p[0], p[1]
    for _ in range(g + 1):
        points.append((x, y))
        x += step_x
        y += step_y
    return points
