To classify a triangle defined by three points, we first validate each point to ensure they are two-dimensional tuples or lists of integers, excluding booleans. Then, we check if the triangle is degenerate using the cross product. If not degenerate, we calculate the squared distances between each pair of points to determine the triangle's side classification and use sorted squared distances to classify the angle.

```python
def triangle_kind(a, b, c):
    for point in [a, b, c]:
        if not (isinstance(point, (list, tuple)) and len(point) == 2):
            raise ValueError
        for coord in point:
            if type(coord) is not int:
                raise ValueError
    ax, ay = a
    bx, by = b
    cx, cy = c
    cross = (bx - ax) * (cy - ay) - (by - ay) * (cx - ax)
    if cross == 0:
        return "degenerate"
    dx1, dy1 = bx - ax, by - ay
    dx2, dy2 = cx - bx, cy - by
    dx3, dy3 = ax - cx, ay - cy
    s_ab = dx1 * dx1 + dy1 * dy1
    s_bc = dx2 * dx2 + dy2 * dy2
    s_ca = dx3 * dx3 + dy3 * dy3
    sides = "isosceles" if s_ab == s_bc or s_bc == s_ca or s_ca == s_ab else "scalene"
    sorted_s = sorted([s_ab, s_bc, s_ca])
    s1, s2, s3 = sorted_s
    if s3 == s1 + s2:
        angle = "right"
    elif s3 > s1 + s2:
        angle = "obtuse"
    else:
        angle = "acute"
    return (sides, angle)
