        if not isinstance(s, int) or isinstance(s, bool):
            raise ValueError("Invalid steps")
        if s < 1 or s > 100:
            raise ValueError("Invalid steps")
        if s in unique_steps:
            raise ValueError("Invalid steps")
        unique_steps.add(s)
    # Validate broken
    if not isinstance(broken, (list, tuple, set)):
        raise ValueError("Invalid broken")
    broken = list(broken)
    broken_set = set()
    for b in broken:
        if not isinstance(b, int) or isinstance(b, bool):
            raise ValueError("Invalid broken")
        if n == 0:
            if len(broken) != 0:
                raise ValueError("Invalid broken")
        else:
            if not (1 <= b <= n - 1):
                raise ValueError("Invalid broken")
        broken_set.add(b)
    # DP setup
    ways = [0] * (n + 1)
    ways[0] = 1
    for i in range(1, n + 1):
        if i in broken_set:
            ways[i] = 0
        else:
            total = 0
            for s in steps:
                if s <= i:
                    total += ways[i - s]
                    total %= MOD
            ways[i] = total
    return ways[n]
