def lcs(a, b):
    if not isinstance(a, str) or not isinstance(b, str):
        raise ValueError
    if len(a) > 300 or len(b) > 300:
        raise ValueError
    n, m = len(a), len(b)
    # Initialize DP table
    L = [[0] * (m + 1) for _ in range(n + 1)]
    # Fill DP table
    for i in reversed(range(n)):
        for j in reversed(range(m)):
            if a[i] == b[j]:
                L[i][j] = 1 + L[i+1][j+1]
            else:
                L[i][j] = max(L[i+1][j], L[i][j+1])
    # Reconstruct LCS
    res = []
    i = j = 0
    while i < n and j < m:
        # Check if current characters match and contribute to LCS
        if a[i] == b[j]:
            res.append(a[i])
            i += 1
            j += 1
        else:
            # Try all possible characters in lex order
            found = False
            # Get all possible characters in both suffixes
            chars_a = set(a[i:])
            chars_b = set(b[j:])
            common_chars = sorted(chars_a & chars_b)
            for c in common_chars:
                # Find first occurrence of c in a[i:] and b[j:]
                x = a.find(c, i)
                y = b.find(c, j)
                if x != -1 and y != -1:
                    # Check if choosing this c leads to a valid LCS
                    if L[x+1][y+1] == L[i][j] - 1:
                        res.append(c)
                        i = x + 1
                        j = y + 1
                        found = True
                        break
            if not found:
                if L[i][j+1] >= L[i+1][j]:
                    j += 1
                else:
                    i += 1
    return ''.join(res)
