def chain_order(dims):
    if not isinstance(dims, (list, tuple)):
        raise ValueError
    n = len(dims)
    if n < 2 or n > 27:
        raise ValueError
    for d in dims:
        if type(d) is not int:
            raise ValueError
        if d < 1 or d > 1000:
            raise ValueError
    m = n - 1
    cost = [[0] * m for _ in range(m)]
    split = [[0] * m for _ in range(m)]

    for l in range(2, n):  # l is chain length (number of matrices)
        for i in range(m - l + 1):
            j = i + l - 1
            cost[i][j] = float('inf')
            for s in range(i, j):
                current = cost[i][s] + cost[s + 1][j] + dims[i] * dims[s + 1] * dims[j + 1]
                if current < cost[i][j]:
                    cost[i][j] = current
                    split[i][j] = s

    def reconstruct(i, j):
        if i == j:
            return chr(ord('A') + i)
        s = split[i][j]
        left = reconstruct(i, s)
        right = reconstruct(s + 1, j)
        return f"({left}{right})"

    if m == 1:
        return (0, "A")
    return (cost[0][m - 1], reconstruct(0, m - 1))

