    return ''.join(snake)

def cidr_range(text):
    # Split into IP and CIDR parts
    if '/' not in text:
        raise ValueError
    ip_part, cidr_str = text.split('/', 1)
    # Validate CIDR part
    if not cidr_str.isdigit() or len(cidr_str) == 0 or (len(cidr_str) > 1 and cidr_str[0] == '0'):
        raise ValueError
    n = int(cidr_str)
    if n < 0 or n > 32:
        raise ValueError
    # Split IP into octets
    octets = ip_part.split('.')
    if len(octets) != 4:
        raise ValueError
    # Validate each octet
    for octet in octets:
        if not octet.isdigit() or (len(octet) > 1 and octet[0] == '0'):
            raise ValueError
        num = int(octet)
        if num < 0 or num > 255:
            raise ValueError
    # Convert IP to integer
    ip_int = 0
    for octet in octets:
        ip_int = (ip_int << 8) | int(octet)
    # Compute mask
    mask = (0xFFFFFFFF << (32 - n)) & 0xFFFFFFFF
    # Compute first and last addresses
    first = ip_int & mask
    last = first | (~mask & 0xFFFFFFFF)
    # Convert back to dotted strings
    def int_to_ip_str(ip):
        return '.'.join(str((ip >> (24 - i*8)) & 0xFF) for i in range(4))
    first_str = int_to_ip_str(first)
    last_str = int_to_ip_str(last)
    # Compute size
    size = 2 ** (32 - n)
    return (first_str, last_str, size)

