from collections import defaultdict, deque

def euler_trail(n, edges):
    if not isinstance(n, int) or n < 0:
        raise ValueError
    if not isinstance(edges, (list, tuple)):
        raise ValueError
    if n == 0:
        if len(edges) != 0:
            raise ValueError
        return []
    for edge in edges:
        if not isinstance(edge, (list, tuple)) or len(edge) != 2:
            raise ValueError
        u, v = edge
        if not isinstance(u, int) or not isinstance(v, int):
            raise ValueError
        if u < 0 or u >= n or v < 0 or v >= n:
            raise ValueError

    in_degree = defaultdict(int)
    out_degree = defaultdict(int)
    for u, v in edges:
        out_degree[u] += 1
        in_degree[v] += 1

    for i in range(n):
        if i not in out_degree:
            out_degree[i] = 0
        if i not in in_degree:
            in_degree[i] = 0

    start = None
    end = None
    for i in range(n):
        diff = out_degree[i] - in_degree[i]
        if diff == 1:
            if start is None:
                start = i
            else:
                return None
        elif diff == -1:
            if end is None:
                end = i
            else:
                return None
        elif diff != 0:
            return None

    if (start is not None) != (end is not None):
        return None

    if start is None:
        for i in range(n):
            if out_degree[i] > 0:
                start = i
                break
        if start is None:
            return []

    out_edges = defaultdict(deque)
    for u, v in edges:
        out_edges[u].append(v)
    for u in out_edges:
        out_edges[u] = deque(sorted(out_edges[u]))

    stack = [start]
    result = []
    while stack:
        current = stack[-1]
        if out_edges[current]:
            next_v = out_edges[current].popleft()
            stack.append(next_v)
        else:
            result.append(stack.pop())
    result = result[::-1]

    if len(result) != len(edges) + 1:
        return None
    return result

