The function `tree_centers` finds the center and radius of a tree by identifying its longest path (diameter) using two breadth-first searches (BFS). The first BFS from any node finds the farthest node `u`. The second BFS from `u` finds the farthest node `v` and the diameter path's length. The radius is half the diameter, rounded up. The center is the middle node(s) of this path.

```python
def tree_centers(n, edges):
    if not isinstance(n, int) or n < 1 or n > 100000:
        raise ValueError
    if not isinstance(edges, (list, tuple)) or len(edges) != n - 1:
        raise ValueError
    for edge in edges:
        if not isinstance(edge, (list, tuple)) or len(edge) != 2:
            raise ValueError
        a, b = edge
        if not isinstance(a, int) or a < 0 or a >= n:
            raise ValueError
        if not isinstance(b, int) or b < 0 or b >= n:
            raise ValueError

    if n == 1:
        return ([0], 0)

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)

    # First BFS to find the farthest node u from 0
    def bfs(start):
        visited = [-1] * n
        q = [start]
        visited[start] = 0
        while q:
            node = q.pop(0)
            for neighbor in adj[node]:
                if visited[neighbor] == -1:
                    visited[neighbor] = visited[node] + 1
                    q.append(neighbor)
        max_dist = max(visited)
        u = visited.index(max_dist)
        return u, visited

    u, _ = bfs(0)
    v, dist = bfs(u)
    D = dist[v]
    radius = (D + 1) // 2

    # Reconstruct path from u to v
    parent = [-1] * n
    q = [u]
    visited = {u}
    while q:
        node = q.pop(0)
        for neighbor in adj[node]:
            if neighbor not in visited:
                parent[neighbor] = node
                visited.add(neighbor)
                q.append(neighbor)

    path = []
    current = v
    while current != u:
        path.append(current)
        current = parent[current]
    path.append(u)
    path = path[::-1]  # Reverse to get u to v

    # Determine centers
    if D % 2 == 0:
        mid = D // 2
        centers = [path[mid]]
    else:
        mid1 = (D - 1) // 2
        mid2 = mid1 + 1
        centers = [path[mid1], path[mid2]]

    centers.sort()
    return (centers, radius)

